#include "neural_chip/PerformanceTelemetryRecorder.h"
namespace dnxr { void PerformanceTelemetryRecorder::record(const StepTelemetrySample& s){ step_.record(s.stepDurationMs); world_.record(s.worldSanitizeDurationMs); state_.record(s.stateGateDurationMs); encoder_.record(s.encoderDurationMs); safety_.record(s.safetyPipelineDurationMs); commit_.record(s.commitDurationMs); replay_.record(s.replayDurationMs); } PercentileStats PerformanceTelemetryRecorder::statsFor(const std::string& f) const { if(f=="worldSanitize") return world_.stats(); if(f=="stateGate") return state_.stats(); if(f=="encoder") return encoder_.stats(); if(f=="safetyPipeline") return safety_.stats(); if(f=="commit") return commit_.stats(); if(f=="replay") return replay_.stats(); return step_.stats(); } PercentileStats PerformanceTelemetryRecorder::totalStats() const { return step_.stats(); } std::map<std::string, PercentileStats> PerformanceTelemetryRecorder::summarize() const { return {{"step",step_.stats()},{"worldSanitize",world_.stats()},{"stateGate",state_.stats()},{"encoder",encoder_.stats()},{"safetyPipeline",safety_.stats()},{"commit",commit_.stats()},{"replay",replay_.stats()}}; } }
